/// <summary>
/// N.Freidenberger 02.05.2025
/// </summary>
/// <param name = "_executionMode">_executionMode</param>
/// <returns>AVAInventItemLocationUpdateController</returns>
public static  AVAInventItemLocationUpdateController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    AVAInventItemLocationUpdateController   controller;
    controller = new AVAInventItemLocationUpdateController();
    controller.parmExecutionMode(_executionMode);
    return controller;
}

/// <summary>
/// N.Freidenberger 
/// </summary>
/// <param name = "_args">_args</param>
public static void main(Args        _args)
{
    AVAInventItemLocationUpdateController       controller;
    controller =   AVAInventItemLocationUpdateController::construct();
    controller.parmArgs(_args);
    controller.startOperation();
}
